mapper.select:
SELECT pr.product_stock_id, pr.stock_code, pr.type, DATE_FORMAT( FROM_UNIXTIME( pr.add_time ), '%Y-%m-%d %H:%i:%s' ) AS addTime, pr.add_by, pr.`COMMENT` AS `comment` FROM product_stock_record pr LEFT JOIN product_stock_record_detail psrd ON psrd.stock_record_id = pr.product_stock_id LEFT JOIN product p ON p.product_id = psrd.product_id LEFT JOIN product_sku ps ON ps.sku_id = psrd.sku_id
AND pr.shop_id = #{productStockDTO.shopId}
AND pr.in_or_out = #{productStockDTO.inOrOut}
AND pr.type = #{productStockDTO.type}
AND pr.add_time >= #{productStockDTO.queryBeginTime}
AND pr.add_time <= #{productStockDTO.queryEndTime}
AND (pr.stock_code like concat('%',#{productStockDTO.keyword},'%') OR p.product_name like concat('%',#{productStockDTO.keyword},'%') OR p.product_sn like concat('%',#{productStockDTO.keyword},'%') OR ps.sku_value like concat('%',#{productStockDTO.keyword},'%'))
GROUP BY pr.product_stock_id order by pr.add_time desc
